WITH parsed AS (SELECT id, service, latency_ms, payload_json, context, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, SHIFTRIGHT(status_code, 2) AS status_code_high, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs) SELECT *, LAG(latency_ms, 1) OVER (PARTITION BY service ORDER BY latency_ms, id) AS prev_latency_ms, AVG(status_code_high) OVER (PARTITION BY service ORDER BY status_code_high, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS status_code_high_avg_3, SUM(status_code_high) OVER (PARTITION BY service ORDER BY status_code_high, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_code_high, RANK() OVER (PARTITION BY service ORDER BY latency_ms NULLS LAST) AS latency_ms_rank FROM parsed;
